import{_ as e,c as a,o as t,a4 as o}from"./chunks/framework.P4k6vdAm.js";const s="/assets/job-datav2.B4lRAfxV.png",n="/assets/job-schedule-visualv2.CMpKXiSX.png",r="/assets/job-schedule-cronv2.8cPrLdVD.png",j=JSON.parse('{"title":"Job Tasks","description":"","frontmatter":{},"headers":[],"relativePath":"docs/tasks/job.md","filePath":"docs/tasks/job.md","lastUpdated":1793099931000}'),i={name:"docs/tasks/job.md"},l=o('<h1 id="job-tasks" tabindex="-1">Job Tasks <a class="header-anchor" href="#job-tasks" aria-label="Permalink to &quot;Job Tasks&quot;">​</a></h1><p>The Job tasks create, update and delete <a href="/docs/triggering/jobs.html">jobs</a> from within an endpoint, instead of manually via the Jobs page. This lets you create, update or delete jobs automatically as needed. There are three tasks:</p><ul><li>Create Job</li><li>Update Job Schedule</li><li>Delete Job</li></ul><h2 id="create-job" tabindex="-1">Create Job <a class="header-anchor" href="#create-job" aria-label="Permalink to &quot;Create Job&quot;">​</a></h2><p><img src="'+s+'" alt="Creating a job"><br> To create a job, ensure <code>Create</code> is the selected option. From here you can name the job, select the endpoint you want to run, what data it should have, and set the schedule. You can also set <code>Disable on failure</code>, to turn the job off if it doesn&#39;t work. You can always turn it back on manually later. The name and the endpoint data can both accept fields from the Context Data panel.</p><p><img src="'+n+'" alt="Creating a job"><br> For setting the schedule, you can either use the visual editor options to set a pattern, or use a <a href="https://en.wikipedia.org/wiki/Cron" target="_blank" rel="noreferrer">cron expression</a>. Cron expressions are in the standard Linux format. For advanced use cases, you can define the schedule using fields from the Context Data panel as well.</p><p><img src="'+r+'" alt="Creating a job"></p><p>When you&#39;re done, click &quot;Save Changes&quot;.</p><h2 id="update-job-schedule" tabindex="-1">Update Job Schedule <a class="header-anchor" href="#update-job-schedule" aria-label="Permalink to &quot;Update Job Schedule&quot;">​</a></h2><p>To update a job schedule you must specify the name of a job that will already exist when the endpoint runs. Then set the schedule as you would when creating a new job.</p><h2 id="delete-job" tabindex="-1">Delete Job <a class="header-anchor" href="#delete-job" aria-label="Permalink to &quot;Delete Job&quot;">​</a></h2><p>To remove a job, choose the Delete Job Task <code>Remove</code>, and enter the job name. Like creating or scheduling a job, this can include data fields from the Context Data panel, and should be the name of the job you want to delete.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>When defining a job name in a Create Job task, try to ensure it will be unique.</li></ul>',14),d=[l];function h(c,u,b,p,m,f){return t(),a("div",null,d)}const k=e(i,[["render",h]]);export{j as __pageData,k as default};
